#[cfg(test)]
mod reliability_proof_tests {
 use super::*;
 #[test] fn ten_thousand_invalid_transitions_are_rejected(){let states=[TradeState::Idle,TradeState::CollectingTicks,TradeState::Analysing,TradeState::ProposalPending,TradeState::ProposalReady,TradeState::BuyPending,TradeState::ContractOpen,TradeState::Settling,TradeState::CooldownOrReanalyse];let mut seed=0x5eed_u64;for _ in 0..10_000{seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);let from=states[(seed as usize)%states.len()];seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);let to=states[(seed as usize)%states.len()];let mut machine=from;let accepted=machine.transition(to);assert_eq!(accepted,from.can_transition(to));assert_eq!(machine,if accepted{to}else{from});}}
 #[tokio::test] async fn ten_thousand_fuzzed_json_inputs_never_open_contract(){let(tx,mut rx)=tokio::sync::broadcast::channel(32);let mut seed=0xc0ffee_u64;for index in 0..10_000{seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);let payload=match index%4{0=>format!(r#"{{"buy":{},"req_id":{}}}"#,seed,index),1=>r#"{"msg_type":"proposal","proposal":{"id":null,"ask_price":"NaN"}}"#.into(),2=>"[[]]{invalid".repeat((seed as usize%8)+1),_=>format!(r#"{{"msg_type":"tick","tick":{{"quote":{},"epoch":-1}}}}"#,seed)};let _=handle_ws_message(&payload,&tx).await;while let Ok(event)=rx.try_recv(){assert!(!matches!(event,ApiEvent::ContractOpened{..}));}}}
 #[test] fn ten_thousand_disconnect_scenarios_never_issue_duplicate_buy(){#[derive(Default)]struct L{buy_sent:bool,reconciling:bool,opened:bool,buys:u32}impl L{fn signal(&mut self){if !self.buy_sent&&!self.opened{self.buy_sent=true;self.buys+=1}}fn disconnect(&mut self){if self.buy_sent&&!self.opened{self.reconciling=true}}fn reconnect(&mut self,found:bool){if self.reconciling{self.opened=found;self.buy_sent=found;self.reconciling=false}}}for scenario in 0..10_000{let mut l=L::default();l.signal();l.disconnect();l.signal();l.reconnect(scenario%2==0);if l.opened{l.signal()}assert_eq!(l.buys,1,"duplicate buy in scenario {scenario}");}}
 #[test] fn deterministic_claim_holds_for_ten_thousand_steps(){let mut first = SeededRng::new(42); let mut second = SeededRng::new(42); for _ in 0..10_000 { assert_eq!(first.next_u64(), second.next_u64()); }}
}
